    /**
     * Minor firmware version
     */
    public var minorVersion: UInt32?
    /**
     * Patch firmware version
     */
    public var patchVersion: UInt32?
    /**
     * Whether PIN protection is enabled
     */
    public var pinProtection: Bool?
