    /**
     * BIP49 wrapped segwit (P2SH-P2WPKH) — ypub/upub prefix
     */
    case wrappedSegwit
    /**
     * BIP84 native segwit (P2WPKH) — zpub/vpub prefix
     */
    case nativeSegwit
    /**
     * BIP86 taproot (P2TR)
     */
    case taproot
}


